let lang='fr';try{lang=localStorage.getItem('havre-language')==='en'?'en':'fr'}catch{}
const t=(fr,en)=>lang==='fr'?fr:en;
const nav=()=>[['home',t('Accueil','Home')],['contact','Contact'],['past',t('Concerts passés','Past events')],['booking','Booking'],['videos',t('Vidéos','Videos')],['donate',t('Faire un don','Donate')],['artists',t('Artistes','Featured artists')],['about',t('À propos','About')],['promotion',t('Promotion','Promotion')]];
const a=(r,text)=>`<a href="#/${r}">${text}</a>`;
const pending=()=>`<p class="muted">${t('À venir.','Coming soon.')}</p>`;
const title=(h,body)=>`<h1>${h}</h1>${body}`;
let bookingType='artist',eventView='list',month=new Date();month.setDate(1);
function socialIcons(){
  const artwork={
    Instagram:'<rect x="3" y="3" width="18" height="18" rx="5" fill="none" stroke="currentColor" stroke-width="1.8"/><circle cx="12" cy="12" r="4" fill="none" stroke="currentColor" stroke-width="1.8"/><circle cx="17.5" cy="6.5" r="1.1" fill="currentColor"/>',
    Facebook:'<path fill="currentColor" d="M14.1 22v-9.1h3.1l.5-3.6h-3.6V7c0-1 .3-1.8 1.8-1.8h1.9V2.1A24 24 0 0 0 15 2c-2.8 0-4.7 1.7-4.7 4.8v2.5H7.2v3.6h3.1V22z"/>',
    YouTube:'<rect x="2" y="5" width="20" height="14" rx="4" fill="none" stroke="currentColor" stroke-width="1.8"/><path d="m10 8 6 4-6 4z" fill="currentColor"/>',
    Twitch:'<path d="M4 2h18v13l-5 5h-5l-3 3v-3H4z" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/><path d="M10 7v6m6-6v6" fill="none" stroke="currentColor" stroke-width="1.8"/>'
  };
  return '<div class="social-icons" role="group" aria-label="'+t('Réseaux sociaux','Social media')+'">'+Object.entries(artwork).map(([name,svg])=>'<span class="social-icon" role="img" aria-label="'+name+' — '+t('lien à venir','link coming soon')+'" title="'+name+' — '+t('lien à venir','link coming soon')+'"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">'+svg+'</svg></span>').join('')+'</div>';
}


function shell(route,body){return `<div class="language"><button data-lang="fr" aria-pressed="${lang==='fr'}">Français</button><span>/</span><button data-lang="en" aria-pressed="${lang==='en'}">English</button></div><header><div class="header-row">${a('home','<span class="wordmark">havre</span>')}${socialIcons()}</div><nav aria-label="${t('Navigation','Navigation')}">${nav().map(([id,label])=>`<a href="#/${id}" ${route===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav></header><main id="main" tabindex="-1">${body}</main><footer><p>${t('Pour toute information à retirer ou à ne plus promouvoir, veuillez nous contacter.','Please contact us about any information you would like removed or no longer promoted.')} ${a('contact','Contact')}</p></footer>`}
function home(){return title('Havre',`<p>${t('Projet musical à but non lucratif à Montpellier.','A not-for-profit music project in Montpellier.')}</p><h2>${t('À venir','Coming soon')}</h2><ul><li>${t('Série de concerts','Concert series')}</li><li>${t('Lieu et studio','Venue and studio')}</li></ul><h2>Booking</h2><p>${t('Mettre en lien artistes et lieux de concert.','Connecting artists and venues.')} ${a('booking',t('En savoir plus','More information'))}</p>`)}
function contact(){return title('Contact',`<dl class="details"><dt>E-mail</dt><dd>${t('À ajouter.','To be added.')}</dd><dt>Instagram</dt><dd>${t('Lien à ajouter.','Link to be added.')}</dd></dl>`)}
function past(){return title(t('Concerts et événements passés','Past concerts and events'),pending())}
function videos(){return title(t('Clips et vidéos des concerts','Clips and concert videos'),pending())}
function donate(){return title(t('Faire un don','Donate'),`<p>${t('La collecte de fonds est en préparation.','Fundraising is in preparation.')}</p><p class="muted">${t('Aucun paiement n’est accepté pour le moment.','No payments are accepted yet.')}</p>`)}
function artists(){return title(t('Artistes','Featured artists'),`<ul><li>${a('artist/jack-de-tombe','Jack De Tombe')}</li><li>${a('artist/david-barnard','David Barnard')}</li></ul>`)}
function davidBarnard(){return title('David Barnard',`<p><a href="https://henzerlingtaos.com/david-barnard/" target="_blank" rel="noopener noreferrer">${t('Présentation de David Barnard','David Barnard’s profile')}</a></p><h2>${t('Vidéo','Video')}</h2><div class="video-player"><iframe src="https://www.youtube-nocookie.com/embed/pa1xtsPTwKI" title="David Barnard — YouTube" allow="encrypted-media; picture-in-picture; fullscreen" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><p class="video-link"><a href="https://www.youtube.com/watch?v=pa1xtsPTwKI" target="_blank" rel="noopener noreferrer">${t('Regarder sur YouTube','Watch on YouTube')}</a></p>`)}

function artist(){return title('Jack De Tombe',`<h2>${t('Présentation','Description')}</h2>${pending()}<h2>${t('Vidéo','Video')}</h2><p class="muted">${t('Lien YouTube à ajouter.','YouTube link to be added.')}</p><h2>${t('Liens','Links')}</h2><ul><li>${t('Site de l’artiste : à ajouter.','Artist website: to be added.')}</li><li>${t('Instagram : à ajouter.','Instagram: to be added.')}</li></ul>`)}
function about(){return title(t('À propos de Havre','About Havre'),`<p>${t('Un projet musical à but non lucratif à Montpellier.','A not-for-profit music project in Montpellier.')}</p><ul><li>${t('Une série de concerts pour soutenir les tournées des artistes.','A concert series to support artists’ tours.')}</li><li>${t('Un futur studio et lieu communautaire.','A future community studio and venue.')}</li><li>${t('Un refuge pour les artistes en tournée.','A refuge for touring artists.')}</li></ul><h2>${t('Fonctionnement prévu','Planned funding model')}</h2><ul><li>${t('10 % des recettes des concerts pour soutenir une résidence ou une tournée dans la région.','10% of show revenue to support an artist residency or tour in the region.')}</li><li>${t('Tous les revenus des frais de booking reviennent à Havre.','All booking-fee earnings go back into Havre.')}</li><li>${t('Tous les fonds sont réinvestis dans Havre, sans collecte à titre privé.','All funds go back into Havre; none are collected privately.')}</li></ul>`)}
function field(n,label,type='text',required=true){return `<label>${label}${required?' *':''}${type==='textarea'?`<textarea name="${n}" rows="4" ${required?'required':''}></textarea>`:`<input name="${n}" type="${type}" ${required?'required':''}>`}</label>`}
const formStatus=()=>`<p class="muted">${t('Les envois ne sont pas encore ouverts.','Submissions are not open yet.')}</p><button type="submit" disabled>${t('Envoyer — bientôt disponible','Submit — coming soon')}</button>`;
function booking(){return title('Booking',`<p>${t('Mettre en lien les artistes avec des lieux de concert, et les lieux avec des artistes.','Connecting artists with venues, and venues with artists.')}</p><p>${t('Tous les revenus des frais de booking reviennent à Havre.','All booking-fee earnings go back into Havre.')}</p><h2>${t('Demandes','Applications')}</h2><div class="tabs"><button data-booking="artist" aria-pressed="${bookingType==='artist'}">${t('Artiste','Artist')}</button><button data-booking="venue" aria-pressed="${bookingType==='venue'}">${t('Lieu','Venue')}</button></div><form><h3>${bookingType==='artist'?t('Demande artiste','Artist application'):t('Demande lieu','Venue application')}</h3>${field('name',bookingType==='artist'?t('Nom de l’artiste','Artist name'):t('Nom du lieu','Venue name'))}${field('email','E-mail','email')}${field('url',t('Site ou lien','Website or link'),'url',false)}${field('description',t('Présentation','Description'),'textarea')}${formStatus()}</form>`)}
function promotion(){return title(t('Promotion','Promotion'),`<div class="tabs"><button data-view="list" aria-pressed="${eventView==='list'}">${t('Liste','List')}</button><button data-view="daily" aria-pressed="${eventView==='daily'}">Daily Run</button><button data-view="calendar" aria-pressed="${eventView==='calendar'}">${t('Calendrier','Calendar')}</button></div><div class="event-controls"><label>${t('Trier par','Sort by')}<select id="sort">${[t('Artiste','Artist'),'Genre','Description',t('Date et heure','Date and time'),t('Lieu','Location'),t('Prix','Price')].map(s=>`<option>${s}</option>`).join('')}</select></label></div><div id="events"></div><p>${a('promotion/submit',t('Proposer un événement','Submit an event'))}</p><p class="muted">${t('Publication quotidienne sur Instagram : à connecter.','Daily Instagram posting: to be connected.')}</p>`)}
function submission(){return title(t('Proposer un événement','Submit an event'),`<form>${field('artist',t('Nom de l’artiste','Artist name'))}${field('genre','Genre')}${field('description',t('Description de l’événement','Event description'),'textarea')}${field('date','Date','date')}${field('time',t('Heure','Time'),'time')}${field('location',t('Lieu','Location'))}<label>${t('Prix (€)','Price (€)')} *<input name="price" type="number" min="0" step="0.01" required></label>${formStatus()}</form>`)}
function renderEvents(){let el=document.getElementById('events');if(!el)return;if(eventView==='calendar'){const y=month.getFullYear(),m=month.getMonth(),offset=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate();let cells='';for(let i=0;i<Math.ceil((offset+days)/7)*7;i++){const d=i-offset+1;cells+=`<div>${d>0&&d<=days?d:''}</div>`}el.innerHTML=`<div class="calendar-head"><button data-month="-1" aria-label="${t('Mois précédent','Previous month')}">←</button><h2>${month.toLocaleDateString(lang==='fr'?'fr-FR':'en-GB',{month:'long',year:'numeric'})}</h2><button data-month="1" aria-label="${t('Mois suivant','Next month')}">→</button></div><div class="calendar">${t('Lun Mar Mer Jeu Ven Sam Dim','Mon Tue Wed Thu Fri Sat Sun').split(' ').map(d=>`<strong>${d}</strong>`).join('')}${cells}</div>${pending()}`;el.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{month.setMonth(month.getMonth()+Number(b.dataset.month));renderEvents()})}else{el.innerHTML=(eventView==='daily'?`<h2>Daily Run — ${new Intl.DateTimeFormat(lang==='fr'?'fr-FR':'en-GB',{timeZone:'Europe/Paris',day:'numeric',month:'long'}).format(new Date())}</h2>`:'')+`<div class="table-scroll"><table><thead><tr>${[t('Artiste','Artist'),'Genre','Description',t('Date et heure','Date and time'),t('Lieu','Location'),t('Prix','Price')].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody><tr><td colspan="6">${t('Aucun événement publié.','No events published.')}</td></tr></tbody></table></div>`}}
function bind(){document.querySelector(".skip").onclick=e=>{e.preventDefault();document.getElementById("main").focus();document.getElementById("main").scrollIntoView()};document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;try{localStorage.setItem('havre-language',lang)}catch{}render(false)});document.querySelectorAll('[data-booking]').forEach(b=>b.onclick=()=>{bookingType=b.dataset.booking;render(false)});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{eventView=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderEvents()});document.querySelectorAll('form').forEach(f=>f.onsubmit=e=>e.preventDefault());renderEvents()}
function render(scroll=true){const route=location.hash.startsWith('#/')?location.hash.slice(2):'home';const pages={home,contact,past,booking,videos,donate,artists,about,promotion,'promotion/submit':submission,'artist/jack-de-tombe':artist,'artist/david-barnard':davidBarnard};document.documentElement.lang=lang;document.title='Havre — '+(route==='artist/david-barnard'?'David Barnard':nav().find(([id])=>id===route)?.[1]||'Montpellier');document.getElementById('app').innerHTML=shell(route.startsWith('artist/')?'artists':route.startsWith('promotion/')?'promotion':route,pages[route]?pages[route]():title('404',a('home',t('Accueil','Home'))));bind();if(scroll)window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>render());render();


